final class OrderAdapter implements IOrderPublisher, MessageListener {
    private final JMSContext ctx;
    private final Queue orders;
    private final OrderHandler app;

    @Override public void publish(Order o) { ctx.createProducer().send(orders, encode(o)); }

    @Override public void onMessage(Message m) {
        try { app.handle(decode(((TextMessage) m).getText())); }
        catch (JMSException e) { /* let the adapter decide: reject or requeue */ }
    }
}

