@Bean
IntegrationFlow orders(OrderHandler app, ConnectionFactory cf) {
    return IntegrationFlow
        .from(Jms.inboundAdapter(cf).destination("orders"))
        .<TextMessage>handle((m, h) -> { app.handle(decode(m.getText())); return null; })
        .get();
}
